float random(float value){
	float mutator = 0.69420;
    float _out = fract(sin(value + mutator) * 42069.80085);
    _out = fract(sin(_out + mutator) * 95453.54515);
    return _out;
}

vec2 random2d(float value0, float value1){
    float mutator0 = 0.80085;
    float mutator1 = 0.42069;
    float val2 = dot(value0, value1);
    return vec2(random(val2 - mutator0), random(val2 - mutator1));
}

vec3 random3d(float value0, float value1, float value2){
    float mutator0 = 0.80085;
    float mutator1 = 0.42069;
    float mutator2 = 3.14159;

    float val3 = value0 * value1 * value2;

    return vec3(random(val3 - mutator0), random(val3 - mutator1), random(val3 - mutator2));
}

float flerp(float val0, float val1, float interpolator){
    return ((1.0 - interpolator) * val0) + (interpolator * val1);
}

vec3 v3lerp(vec3 val0, vec3 val1, float interpolator){
    float x = ((1.0 - interpolator) * val0.x) + (interpolator * val1.x);
    float y = ((1.0 - interpolator) * val0.y) + (interpolator * val1.y);
    float z = ((1.0 - interpolator) * val0.z) + (interpolator * val1.z);
    return vec3(x,y,z);
}

float easeIn(float val){
    return val * val;
}

float easeOut(float val){
    return 1.0 - easeIn(1.0 - val);
}

float easeInOut(float val){
    return flerp(easeIn(val), easeOut(val), val);
}

float gradientNoise(float value){
    float decimal = fract(value);
    float line0gradient = (random(floor(value)) * 2.0) - 1.0;
    float line0point = line0gradient * decimal;
    float line1gradient = (random(ceil(value)) * 2.0) - 1.0;
    float line1point = line1gradient * (decimal - 1.0);

    return flerp(line0point, line1point, easeInOut(decimal));
}

float Perlin(vec2 value){
    vec2 decimal = fract(value);

    vec2 x0y0direction = random2d(floor(value.x), floor(value.y)) * 2.0 - 1.0;
    vec2 x0y1direction = random2d(floor(value.x), ceil(value.y)) * 2.0 - 1.0;
    vec2 x1y0direction = random2d(ceil(value.x), floor(value.y)) * 2.0 - 1.0;
    vec2 x1y1direction = random2d(ceil(value.x),ceil(value.y)) * 2.0 - 1.0;    

    float x0y0point = dot(x0y0direction, decimal - vec2(0.0,0.0));
    float x0y1point = dot(x0y1direction, decimal - vec2(0.0,1.0));
    float x1y0point = dot(x1y0direction, decimal - vec2(1.0,0.0));
    float x1y1point = dot(x1y1direction, decimal - vec2(1.0,1.0));


    float y0points = flerp(x0y0point, x1y0point, easeInOut(decimal.x));
    float y1points = flerp(x0y1point, x1y1point, easeInOut(decimal.x));
    float final = flerp(y0points, y1points, easeInOut(decimal.y));

    return final;
}

float Perlin3(vec3 value){
    vec3 decimal = fract(value);//use the intergers as the grid... love this strategy

    //get some gradient vectors
    vec3 x0y0z0direction = random3d(floor(value.x), floor(value.y), floor(value.z));
    vec3 x0y0z1direction = random3d(floor(value.x), floor(value.y), ceil(value.z));
    vec3 x0y1z0direction = random3d(floor(value.x), ceil(value.y), floor(value.z));
    vec3 x0y1z1direction = random3d(floor(value.x), ceil(value.y), ceil(value.z));
    vec3 x1y0z0direction = random3d(ceil(value.x), floor(value.y), floor(value.z));
    vec3 x1y0z1direction = random3d(ceil(value.x), floor(value.y), ceil(value.z));
    vec3 x1y1z0direction = random3d(ceil(value.x), ceil(value.y), floor(value.z));
    vec3 x1y1z1direction = random3d(ceil(value.x), ceil(value.y), ceil(value.z));

    //interperet the vectors
    float x0y0z0point = dot(x0y0z0direction, decimal - vec3(0.0,0.0,0.0));
    float x0y0z1point = dot(x0y0z1direction, decimal - vec3(0.0,0.0,1.0));
    float x0y1z0point = dot(x0y1z0direction, decimal - vec3(0.0,1.0,0.0));
    float x0y1z1point = dot(x0y1z1direction, decimal - vec3(0.0,1.0,1.0));
    float x1y0z0point = dot(x1y0z0direction, decimal - vec3(1.0,0.0,0.0));
    float x1y0z1point = dot(x1y0z1direction, decimal - vec3(1.0,0.0,1.0));
    float x1y1z0point = dot(x1y1z0direction, decimal - vec3(1.0,1.0,0.0));
    float x1y1z1point = dot(x1y1z1direction, decimal - vec3(1.0,1.0,1.0));

    //lerp(smoothly) between the adjacent grids
    float x0y0points = flerp(x0y0z0point, x0y0z1point, easeInOut(decimal.z));
    float x0y1points = flerp(x0y1z0point, x0y1z1point, easeInOut(decimal.z));
    float x1y0points = flerp(x1y0z0point, x1y0z1point, easeInOut(decimal.z));
    float x1y1points = flerp(x1y1z0point, x1y1z1point, easeInOut(decimal.z));

    float x0points = flerp(x0y0points, x0y1points, easeInOut(decimal.y));
    float x1points = flerp(x1y0points, x1y1points, easeInOut(decimal.y));

    float final = flerp(x0points, x1points, easeInOut(decimal.x));

    return final;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float y_effect = 1.0 - (iMouse.y / iResolution.y);
    float effect_intensity = (iMouse.y /iResolution.y) * (1.0 - (uv.y * y_effect));

    uv.y += y_effect;

    //set up some colours
    vec3 col1 = vec3(0.204,0.306,0.255);//dark green
    vec3 col2 = vec3(0.733,0.835,0.557);//light green
    vec3 col3 = vec3(0.204,0.0,0.0);//dark red
    vec3 col4 = vec3(0.404, 0.0, 0.0);//less dark red
    vec3 col5 = vec3(1.0,0.118,0.0);//orange

    //pixel color
    vec3 col = vec3(0.0,0.0,0.0);

    //distance from line as defined

    //interperet uv
    vec3 start = vec3(10.0,10.0, 10.0);
    float xrange = 3.0;
    vec2 range = vec2(xrange, xrange/1.778);
    vec3 position = vec3(uv.x * range.x, uv.y * range.y, iTime/40.0) + start;
    vec3 position2 = vec3(uv.x * range.x * 2.0, uv.y * range.y * 2.0, iTime/40.0) + start + (iTime/3.0);

    float a = Perlin3(position) + 0.5;
    float b = Perlin3(position2)/10.0;

    //bandify the noise
    float bandInterval = flerp(0.04, 0.01, ((sin(iTime/20.0) + 1.0) / 2.0));//didn't know 'mix' existed when I wrote this
    float currentPos = 0.0;
    float polarity = 1.0;

    float adjustedValue = clamp(a + b, 0.0, 1.0);

    for(currentPos = 0.0; currentPos <= 1.0; currentPos += bandInterval){
        float dp = abs(a - currentPos);

        if(a > currentPos){

            switch(int(polarity)){
                case 1:
                adjustedValue = dp/bandInterval;
                break;
                case -1:
                adjustedValue = (1.0 - dp/bandInterval);
                break;
            };
        };

        polarity *= -1.0;
    };

    uv = fragCoord / iResolution.xy;
    uv.x += ((adjustedValue-0.5) / 10.0) * effect_intensity;


    //col = vec3(adjustedValue,adjustedValue,adjustedValue);

    col = texture(iChannel0, uv).rgb;


    // Output to screen
    fragColor = vec4(col,1.0);
}

vec4 HSVtoRGB(vec4 hsvcol){
	//make rgb from hsv
    float hue = hsvcol.x * 360.0;
	float sat = hsvcol.y;
	float val = hsvcol.z;
    float alpha = hsvcol.a;

	float _c = val * sat;
	float _x = _c * (1.0 - abs(mod(hue / 60.0, 2.0) - 1.0));
	float _m = val - _c;

	vec4 outcol = vec4(0.0, 0.0, 0.0, alpha);

	if(hue < 60.0){
		outcol = vec4(_c, _x, 0.0, alpha);
	} else if(hue < 120.0){
		outcol = vec4(_x, _c, 0.0, alpha);	
	} else if(hue < 180.0){
		outcol = vec4(0.0, _c, _x, alpha);
	} else if(hue < 240.0){
		outcol = vec4(0.0, _x, _c, alpha);
	} else if(hue < 300.0){
		outcol = vec4(_x, 0.0, _c, alpha);
	} else {
		outcol = vec4(_c, 0.0, _x, alpha);
	};

	outcol += _m;
    return(outcol);
}

vec4 RGBtoHSV(vec4 rgbcol){
    float red = rgbcol.r;
    float green = rgbcol.g;
    float blue = rgbcol.b;
    float alpha = rgbcol.a;

    float maxc = max(green,max(red,blue));
    float minc = min(red,min(green,blue));
    float rangec = maxc - minc;

    float val = maxc;
    if(maxc == minc){//early break for greyscale (when would this ever happen lol)
        return(vec4(0.0, 0.0, val, alpha));
    };

    float sat = rangec / maxc;

    float hue = 0.5;
    float rc = (maxc - red) / rangec;
    float gc = (maxc - green) / rangec;
    float bc = (maxc - blue) / rangec;

    if(red == maxc){
        hue = 0.0 + bc - gc;
    }else if(green == maxc){
        hue = 2.0 + rc - bc;
    }else{
        hue = 4.0 + gc - rc;
    };

    if(hue < 0.0){
        hue += 6.0;
    };
    hue /= 6.0;

    return(vec4(hue, sat, val, alpha));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    uv.x = round(uv.x * 11.0) / 11.0;
    float hue = uv.x;

    fragColor = HSVtoRGB(vec4(hue, 1.0, 1.0, 1.0));
}
